function accountsDialog(){const m=modal('Server accounts');const url=field(m,'Server URL','login-base',native?JSON.parse(Orbit.computerConfig()).base:'https://your-server.example');const user=field(m,'Username','login-user','');const password=field(m,'Password','login-password','','password');add(m,button('Sign in',()=>nativeOnly(()=>{const value=password.value;password.value='';Orbit.computerUserLogin(url.value,user.value,value);$('modal').close();}),'primary'),button('Manage accounts',()=>nativeOnly(()=>Orbit.computerRequest('/users','GET',''))),button('Create account',createAccount),para('Accounts share one server desktop. Roles do not create isolated machines. Sessions expire after 24 hours. Server owners create accounts; passwords are not included in exports.'));}
function createAccount(){const m=modal('Create server account');field(m,'Username','new-user','');const p=field(m,'Password (at least 12 characters)','new-password','','password');const role=el('select',{'aria-label':'Account role'});for(const v of ['viewer','reviewer','owner'])role.append(el('option',{value:v},v));m.append(role);m.append(button('Create',()=>nativeOnly(()=>{const value=p.value;p.value='';Orbit.computerRequest('/users','POST',JSON.stringify({username:$('new-user').value,password:value,role:role.value}));$('modal').close();}),'primary'));}
function ragDialog(){const m=modal('Semantic knowledge');const query=field(m,'Search query','semantic-query','');m.append(para('Uses your server’s configured embedding model; requests may be billed. Import a file into server knowledge and explicitly index it first.'));add(m,button('Search indexed documents',()=>nativeOnly(()=>Orbit.computerRequest('/rag/search','POST',JSON.stringify({query:query.value}))),'primary'),button('Index a document ID',()=>{const next=modal('Index server document');const id=field(next,'Document ID from knowledge upload','index-document','');next.append(button('Create embeddings',()=>nativeOnly(()=>Orbit.computerRequest('/rag/index','POST',JSON.stringify({document_id:id.value}))),'primary'));}));}
function handleTools(event){const path=event.path,data=event.data;if(path==='/connectors'){const m=modal('Connected accounts');for(const c of data.connectors||[]){const card=el('div',{class:'panel'});add(card,el('h3',{},c.id),para(c.connected?'Connected':c.configured?'Ready to authorize':'Server OAuth app registration required'),button(c.connected?'Browse account':'Connect',()=>nativeOnly(()=>Orbit.computerRequest('/connectors/'+c.id+(c.connected?'/items':'/start'),c.connected?'GET':'POST','{}'))));if(c.connected)add(card,button('Queue a write',()=>connectorWrite(c.id)),button('Disconnect locally',()=>nativeOnly(()=>{if(confirm('Remove this account connection from Orbit?'))Orbit.computerRequest('/connectors/'+c.id,'DELETE','');})));m.append(card);}return true;}if(path.startsWith('/connectors/')){if(data.authorization_url){nativeOnly(()=>Orbit.link(data.authorization_url));toast('Finish authorization in your browser, then reopen Connected apps.');}else showJSON('Connected app',data);return true;}
 if(path==='/media'){if(data.id){toast('Media request queued');nativeOnly(()=>Orbit.computerRequest('/media','GET',''));}else showMedia(data);return true;}if(path.startsWith('/media/')){toast('Media status updated');nativeOnly(()=>Orbit.computerRequest('/media','GET',''));return true;}if(path.startsWith('/rag/')){showJSON('Semantic knowledge',data);return true;}if(path==='/knowledge'&&data.id){const m=modal('Knowledge uploaded');add(m,para('Document ID: '+data.id),button('Index for semantic search',()=>nativeOnly(()=>Orbit.computerRequest('/rag/index','POST',JSON.stringify({document_id:data.id}))),'primary'));return true;}if(path==='/users'){if(data.users){const m=modal('Server users');for(const u of data.users){const row=el('div',{class:'panel'});add(row,el('strong',{},u.id+' · '+u.role),para(u.disabled?'Disabled':'Active'),button('Disable',()=>nativeOnly(()=>{if(confirm('Disable '+u.id+' and revoke sessions?'))Orbit.computerRequest('/users/'+encodeURIComponent(u.id)+'/disable','POST','{}');})));m.append(row);}}else toast('Account created');return true;}if(path.startsWith('/users/')){toast('Account updated');return true;}
 if(path==='/payments'){const m=modal('Stripe Checkout');add(m,para(data.configured?'Merchant key configured. Payment status is confirmed by signed webhooks.':'Configure your Stripe merchant account on the server.'),button('Create checkout request',checkoutDialog,'primary'));for(const c of data.checkouts||[])add(m,add(el('div',{class:'panel'}),el('strong',{},c.status),button('Open payment link',()=>nativeOnly(()=>Orbit.link(c.url)))));return true;}if(path.startsWith('/payments/')){toast('Checkout request queued. Review it in Computer.');return true;}return false;}
function showJSON(title,data){const m=modal(title);m.append(el('pre',{class:'file-preview'},JSON.stringify(data,null,2)));}
function connectorWrite(provider){if(!['google','microsoft','notion','figma'].includes(provider)){toast('This connector currently supports read-only browsing.');return;}const m=modal('Prepare '+provider+' action');let payload,operation;if(provider==='google'||provider==='microsoft'){field(m,'Recipient','connector-to','','email');field(m,'Subject','connector-subject','');field(m,'Message','connector-text','','textarea');operation='send';payload=()=>({to:$('connector-to').value.trim(),subject:$('connector-subject').value,text:$('connector-text').value});}else if(provider==='figma'){field(m,'Figma file key','connector-file','');field(m,'Comment','connector-text','','textarea');operation='comment';payload=()=>({file:$('connector-file').value.trim(),message:$('connector-text').value});}else{field(m,'Parent page ID (shared with the Notion connection)','connector-parent','');field(m,'Page title','connector-title','');field(m,'Paragraph (up to 2,000 characters)','connector-text','','textarea');operation='create_page';payload=()=>({parent:{page_id:$('connector-parent').value.trim()},properties:{title:{type:'title',title:[{type:'text',text:{content:$('connector-title').value}}]}},children:[{object:'block',type:'paragraph',paragraph:{rich_text:[{type:'text',text:{content:$('connector-text').value}}]}}]});}m.append(para('This queues an exact request for review in Computer. Reconnecting an account invalidates its earlier queued writes.'));m.append(button('Queue for review',()=>nativeOnly(()=>{const body=payload();Orbit.computerRequest('/connectors/'+provider+'/write','POST',JSON.stringify({operation,payload:body}));$('modal').close();}),'primary'));}
function checkoutDialog(){const m=modal('Create a payment link');field(m,'Product or service','checkout-name','');field(m,'Amount in smallest currency units (e.g. INR paise)','checkout-amount',10000,'number');field(m,'Currency code','checkout-currency','inr');m.append(para('Creates a Stripe Checkout link after approval. It does not charge anyone automatically or guarantee payment.'));m.append(button('Queue checkout',()=>nativeOnly(()=>{Orbit.computerRequest('/payments/checkout','POST',JSON.stringify({name:$('checkout-name').value,amount:Number($('checkout-amount').value),currency:$('checkout-currency').value.toLowerCase()}));$('modal').close();}),'primary'));}
function showMedia(data){const m=modal('Media studio');for(const kind of ['image','video','speech'])m.append(button('Create '+kind+(data.configured?.[kind]?'':' · needs setup'),()=>{const next=modal('Create '+kind);const prompt=field(next,kind==='speech'?'Text to speak':'Prompt','media-prompt','','textarea');next.append(para('Uses your server’s configured model and credits. One request is queued; failures are not automatically retried.'));next.append(button('Generate',()=>nativeOnly(()=>{Orbit.computerRequest('/media','POST',JSON.stringify({kind,prompt:prompt.value}));$('modal').close();}),'primary'));}));m.append(button('Transcribe audio file',()=>nativeOnly(()=>{if(confirm('Send a chosen audio file (up to 8 MB) to your server’s transcription provider? Provider charges may apply.'))Orbit.transcribeAudio();})));m.append(button('Refresh jobs',()=>nativeOnly(()=>Orbit.computerRequest('/media','GET',''))));for(const item of data.media||[]){const row=el('div',{class:'panel'});let result;try{result=JSON.parse(item.result);}catch(_){result={text:item.result};}add(row,el('strong',{},item.kind+' · '+item.state));if(result.text)row.append(para(result.text));if(result.filename)row.append(button('Save to phone',()=>nativeOnly(()=>Orbit.saveMedia(item.id))));if(result.url)row.append(button('Open provider video',()=>nativeOnly(()=>Orbit.link(result.url))));if(item.state==='pending_video')row.append(button('Check video',()=>nativeOnly(()=>Orbit.computerRequest('/media/'+item.id+'/check','POST','{}'))));m.append(row);}}
